25	    private MembershipPointsDeriver() {
26	    }
27	
28	    /**
29	     * Returns the owner's membership points, derived from the owner's own fields.
30	     */
31	    public static int membershipPoints(Owner owner) {
32	        int points = 0;
33	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
34	            points += 2;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            points += 1;
38	        }
39	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
40	            points += 2;
41	        }
42	        if (owner.getRegistrationDate() != null
43	            && FiscalYearDeriver.elapsedFiscalYears(owner.getRegistrationDate(), LocalDate.now()) > 1) {
44	            points += 3;
45	        }
46	        return points;
47	    }
48	
49	    /**
50	     * Returns the owner's effective membership level: the stored level when one has been
51	     * assigned (e.g. a household-capped level fixed at creation), otherwise the level derived
52	     * from the owner's own membership points.
53	     */
54	    public static int effectiveMembershipLevel(Owner owner) {
55	        if (owner.getMembershipLevel() != null) {
56	            return owner.getMembershipLevel();
57	        }
58	        return membershipLevel(membershipPoints(owner));
59	    }
60	
61	    /**
62	     * Returns the membership level for the given membership points: 1 for 0-1 points,
63	     * 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
64	     */
65	    public static int membershipLevel(int points) {
66	        if (points <= 1) {
67	            return 1;
68	        }
69	        if (points <= 3) {
70	            return 2;
71	        }
72	        if (points <= 5) {
73	            return 3;
74	        }
75	        return 4;
76	    }
